<?php defined('BASEPATH') OR exit('No direct script access allowed');$status_labels=['pending'=>'Menunggu','running'=>'Berjalan','success'=>'Berhasil','failed'=>'Gagal'];$status_classes=['pending'=>'bg-yellow-lt text-yellow','running'=>'bg-blue-lt text-blue','success'=>'bg-green-lt text-green','failed'=>'bg-red-lt text-red'];$days=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu']; ?>
<div class="page-header d-print-none"><div class="container-xl"><div class="row g-2 align-items-center"><div class="col"><div class="page-pretitle">Pengaturan Sistem</div><h1 class="page-title">Backup Database Berkala</h1></div><?php if($can_run):?><div class="col-auto ms-auto"><?=form_open('system/database-backups/run',['class'=>'d-inline','onsubmit'=>"return confirm('Jalankan backup database sekarang?');"]);?><button class="btn btn-primary"><i class="ti ti-database-export me-1"></i>Backup Sekarang</button><?=form_close();?></div><?php endif;?></div></div></div>
<div class="page-body"><div class="container-xl"><?php if($this->session->flashdata('success')):?><div class="alert alert-success"><?=html_escape($this->session->flashdata('success'));?></div><?php endif;?><?php if($this->session->flashdata('error')):?><div class="alert alert-danger"><?=html_escape($this->session->flashdata('error'));?></div><?php endif;?><div class="row row-cards"><div class="col-lg-5"><div class="card admin-card"><div class="card-header"><h2 class="card-title">Jadwal dan Retensi</h2></div><?=form_open('system/database-backups/update');?><div class="card-body"><label class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="is_enabled" value="1" <?=!empty($settings['is_enabled'])?'checked':'';?> <?=$can_edit?'':'disabled';?>><span class="form-check-label"><strong>Backup otomatis aktif</strong><small class="d-block text-secondary">Cron memeriksa jadwal setiap menit, tetapi dump hanya dibuat saat jadwal jatuh tempo.</small></span></label><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Frekuensi</label><select class="form-select" name="frequency" <?=$can_edit?'':'disabled';?>><?php foreach(['daily'=>'Harian','weekly'=>'Mingguan','monthly'=>'Bulanan']as$v=>$l):?><option value="<?=$v;?>" <?=$settings['frequency']===$v?'selected':'';?>><?=$l;?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Jam backup</label><input class="form-control" type="time" name="run_time" value="<?=html_escape(substr($settings['run_time'],0,5));?>" <?=$can_edit?'':'disabled';?>></div><div class="col-md-6 mb-3"><label class="form-label">Hari mingguan</label><select class="form-select" name="day_of_week" <?=$can_edit?'':'disabled';?>><?php foreach($days as$i=>$day):?><option value="<?=$i;?>" <?=(int)$settings['day_of_week']===$i?'selected':'';?>><?=$day;?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Tanggal bulanan</label><input class="form-control" type="number" min="1" max="28" name="day_of_month" value="<?=(int)$settings['day_of_month'];?>" <?=$can_edit?'':'disabled';?>></div><div class="col-md-6 mb-3"><label class="form-label">Jumlah file disimpan</label><input class="form-control" type="number" min="2" max="365" name="retention_count" value="<?=(int)$settings['retention_count'];?>" <?=$can_edit?'':'disabled';?>></div><div class="col-md-6 mb-3 d-flex align-items-end"><label class="form-check"><input class="form-check-input" type="checkbox" name="compress_backup" value="1" <?=!empty($settings['compress_backup'])?'checked':'';?> <?=$can_edit?'':'disabled';?>><span class="form-check-label">Kompres GZIP</span></label></div></div><div class="alert alert-info small mb-0"><i class="ti ti-shield-lock me-1"></i>Lokasi privat: <code><?=html_escape($backup_directory);?></code>. File hanya dapat diunduh oleh petugas berizin.</div></div><?php if($can_edit):?><div class="card-footer text-end"><button class="btn btn-primary"><i class="ti ti-device-floppy me-1"></i>Simpan Pengaturan</button></div><?php endif;?><?=form_close();?></div></div>
<div class="col-lg-7"><div class="card admin-card"><div class="card-header"><h2 class="card-title">Riwayat Backup</h2></div><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>Waktu</th><th>Pemicu</th><th>Status</th><th>File</th><th></th></tr></thead><tbody><?php if(empty($runs)):?><tr><td colspan="5" class="text-center text-secondary py-4">Belum ada riwayat backup.</td></tr><?php endif;?><?php foreach($runs as$run):?><tr><td><div><?=date('d M Y H:i',strtotime($run['created_at']));?></div><?php if($run['finished_at']):?><small class="text-secondary">Selesai <?=date('H:i:s',strtotime($run['finished_at']));?></small><?php endif;?></td><td><?=$run['trigger_type']==='manual'?'Manual':'Terjadwal';?></td><td><span class="badge <?=$status_classes[$run['status']]??'bg-secondary-lt';?>"><?=$status_labels[$run['status']]??$run['status'];?></span><?php if($run['message']):?><div class="small text-secondary mt-1" style="max-width:230px"><?=html_escape($run['message']);?></div><?php endif;?></td><td><?php if($run['file_name']):?><div class="fw-semibold"><?=html_escape($run['file_name']);?></div><small class="text-secondary"><?=number_format((int)$run['file_size']/1048576,2,',','.');?> MB</small><?php else:?>—<?php endif;?></td><td><?php if($run['status']==='success'&&!empty($run['file_path'])):?><a class="btn btn-sm btn-outline-primary" href="<?=base_url('system/database-backups/download/'.(int)$run['id']);?>"><i class="ti ti-download"></i></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></div>
